```pli
READFILE: PROCEDURE OPTIONS(MAIN);
  DCL INFILE FILE RECORD INPUT;
  DCL INREC CHAR(80);
  DCL EOF BIT(1) INIT('0'B);

  ON ENDFILE(INFILE) EOF = '1'B;

  OPEN FILE(INFILE);
  READ FILE(INFILE) INTO(INREC);
  DO WHILE(^EOF);
    PUT SKIP LIST(INREC);
    READ FILE(INFILE) INTO(INREC);
  END;
  CLOSE FILE(INFILE);
END READFILE;
```

